-- Step 0 (optional): create tables if they do not exist yet
CREATE TABLE IF NOT EXISTS training_modules (
  id TEXT PRIMARY KEY NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  summary TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL DEFAULT 'module',
  duration_minutes INTEGER NOT NULL DEFAULT 15,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_published INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS training_tests (
  id TEXT PRIMARY KEY NOT NULL,
  module_id TEXT NOT NULL,
  title TEXT NOT NULL,
  passing_score INTEGER NOT NULL DEFAULT 80,
  questions_json TEXT NOT NULL DEFAULT '[]',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);


-- Step 1: run this by itself first
INSERT INTO training_modules (
  id, slug, title, summary, body, kind, duration_minutes, sort_order, is_published, created_at, updated_at
) VALUES (
  'tm_l2pro_construction',
  'xgrids-l2pro-construction',
  'XGRIDS Lixel L2 Pro for Construction',
  'Interactive field-to-office training for the Lixel L2 Pro — LixelGO capture, RTK/GCP georeferencing, LixelStudio point clouds, and LCC Studio Gaussian Splats for construction documentation.',
  '{"version":1,"interactive":true,"chapters":[{"id":"meet-l2pro","eyebrow":"Chapter 1 · Know the kit","title":"Meet the Lixel L2 Pro","blocks":[{"type":"text","markdown":"## Campus-scale scanner for measured work\n\nThe XGRIDS **Lixel L2 Pro** is a handheld Multi-SLAM scanner (LiDAR + visual + IMU) built for construction, surveying, and multi-building sites.\n\nUnlike PortalCam (visualization-first 3DGS), the L2 Pro delivers **point clouds and 3D Gaussian Splats** from the same capture — measured deliverables plus photoreal walkthroughs."},{"type":"video","title":"L2 Pro accuracy in the field","youtubeId":"txgLYGxajdI","caption":"Independent accuracy discussion of the Lixel L2 Pro — useful context for measured construction work.","sourceLabel":"Watch on YouTube","sourceUrl":"https://www.youtube.com/watch?v=txgLYGxajdI"},{"type":"callout","tone":"tip","title":"Platform basics","body":"Shared across L2 Pro configs: ~1.7 kg without battery, 1 TB SSD, ~90 min battery, IP54 aluminum body, LiDAR FOV 360° × 270°, absolute accuracy ≤3 cm RMSE with RTK or GCPs."},{"type":"checklist","title":"Three hardware configs","items":["16/120 — 16 channels, 120 m range, 320k pts/s (entry AEC)","32/120 — 32 channels, 120 m range, 640k pts/s (most professional AEC work)","32/300 — 32 channels, 300 m range, 640k pts/s (tunnels, tall structures, large outdoor sites)"]},{"type":"resource","title":"XGRIDS L2 Pro downloads & support","url":"https://xgrids.com/support/download?page=L2Pro","description":"Official firmware, manuals, and L2 Pro support downloads from XGRIDS."},{"type":"quiz","id":"q-meet-output","prompt":"What can a single L2 Pro scan feed?","choices":["Only CAD linework — no imagery","Point clouds in LixelStudio and 3DGS in LCC Studio","Thermal reports only","PortalCam LCC Scan projects exclusively"],"correctIndex":1,"explanation":"One L2 Pro capture can be processed as a measured point cloud (LixelStudio) and as a Gaussian Splat visualization (LCC Studio)."},{"type":"minigame","kind":"match","id":"game-meet-match","title":"Match the L2 Pro toolkit","prompt":"Pair each piece with its job on a construction capture.","pairs":[{"term":"L2 Pro","definition":"Handheld Multi-SLAM LiDAR scanner"},{"term":"LixelGO","definition":"Mobile app for field control and monitoring"},{"term":"LixelStudio","definition":"Desktop app for measured point clouds"},{"term":"LCC Studio","definition":"Desktop/cloud path for 3D Gaussian Splats"}],"success":"Toolkit locked in — L2 Pro is not PortalCam’s app stack."}]},{"id":"construction-use-cases","eyebrow":"Chapter 2 · Why L2 Pro on site","title":"Construction use cases that need measurement","blocks":[{"type":"text","markdown":"## When the deliverable has to be measured\n\nPick L2 Pro when stakeholders need **coordinates, clearances, quantities, or BIM verification** — not just a pretty walkthrough.\n\nCampus and multi-building routes, mixed indoor/outdoor loops, warehouses, and RTK/GCP georeferenced as-builts are core L2 Pro territory."},{"type":"checklist","title":"High-value L2 Pro construction missions","items":["Multi-building campus or site documentation in one campaign","Large commercial interiors and warehouses","Mixed indoor/outdoor routes without swapping devices mid-day","RTK or GCP georeferenced as-builts for survey/BIM handoff","Quantity / clearance checks against design intent","Tunnels and long outdoor runs (especially 32/300)"]},{"type":"callout","tone":"warn","title":"Wrong tool check","body":"If the only deliverable is a photoreal owner walkthrough with no measured point cloud, PortalCam may be enough. Do not plan survey-grade measured work on PortalCam alone."},{"type":"scenario","title":"Jobsite scenario: warehouse clearances","situation":"An owner needs racking clearances verified against design (±3 cm class) across a 200,000 sq ft warehouse, plus a shareable visual for remote PMs. What capture plan fits?","choices":[{"label":"Phone photos and a tape measure for a few bays","feedback":"Too sparse. You need continuous spatial coverage and a measured cloud."},{"label":"L2 Pro handheld loops for a measured point cloud, with LCC Studio if a walkthrough is also needed","feedback":"Correct. L2 Pro covers measured clearances; the same data can feed a splat walkthrough when useful.","correct":true},{"label":"PortalCam only — it has LiDAR too","feedback":"PortalCam is 3DGS-first and does not produce the measured point-cloud deliverable this job needs."}]},{"type":"minigame","kind":"rapid","id":"game-construction-rapid","title":"Measured vs visual — speed round","prompt":"True or false for L2 Pro construction planning.","passScore":3,"rounds":[{"statement":"L2 Pro can produce both point clouds and 3DGS from the same scan.","correct":true,"explanation":"One capture feeds LixelStudio and LCC Studio."},{"statement":"PortalCam is the better solo choice for survey-grade measured as-builts.","correct":false,"explanation":"PortalCam does not produce point-cloud measured deliverables."},{"statement":"Absolute ≤3 cm accuracy on L2 Pro assumes RTK or GCP coverage with disciplined gaps.","correct":true,"explanation":"Absolute accuracy claims require georeferencing discipline — not handheld luck."},{"statement":"Map Fusion can freely mix 16-channel and 32-channel L2 Pro scans.","correct":false,"explanation":"Map Fusion requires matching L2 Pro model configurations."}],"success":"Good judgment — you know when L2 Pro is the right tool."}]},{"id":"field-kit","eyebrow":"Chapter 3 · LixelGO in the field","title":"Power up, pair, and capture with LixelGO","blocks":[{"type":"text","markdown":"## Field software = LixelGO (not LCC Scan)\n\nL2 Pro and K2 use **LixelGO**. PortalCam uses **LCC Scan**. The apps are not interchangeable — install the right one before you leave the yard.\n\nTypical Direct Connect flow: enable the phone hotspot → LixelGO discovers the scanner over Bluetooth → scanner joins the hotspot → confirm battery, storage, and firmware before you scan."},{"type":"callout","tone":"tip","title":"Preflight checklist","body":"Battery locked (audible click), firmware updated in the office (never mid-job), storage checked (~60–80 GB per hour on the 1 TB SSD), and connection tested before you drive out."},{"type":"checklist","title":"First-scan rhythm","items":["Power on (~3 s hold) and wait until the scanner is ready","Connect in LixelGO and confirm status (battery / storage / firmware)","If using RTK: wait for Fixed — never start on Float","Place on a stable surface and start recording","Hold still through the ~15 s static initialization, then wait before lifting","Walk smooth loops; keep the scanner orientation steady","Stop cleanly and wait for save (solid green) before powering off"]},{"type":"resource","title":"LixelGO setup guide","url":"https://www.alpinerealitycapture.com/guide/lixelgo-setup","description":"Field connection modes (Direct Connect vs Bridge Mode) and first-time LixelGO setup."},{"type":"quiz","id":"q-field-app","prompt":"Which mobile app controls the L2 Pro in the field?","choices":["LCC Scan","LixelGO","Revit Go","PortalCam Companion"],"correctIndex":1,"explanation":"LixelGO is the field app for L2 Pro and K2. LCC Scan is for PortalCam."},{"type":"minigame","kind":"order","id":"game-field-order","title":"Order the field start","prompt":"Put these L2 Pro start steps in the right order.","items":["Confirm LixelGO connection and device status","Hold still for static initialization","Begin walking the planned route","Power on the L2 Pro"],"correctOrder":[3,0,1,2],"success":"Clean start — initialization first, walking second."}]},{"id":"site-playbook","eyebrow":"Chapter 4 · Capture craft","title":"Jobsite scanning playbook","blocks":[{"type":"text","markdown":"## Walk like the cloud depends on it\n\nPlan routes that close loops, revisit distinctive geometry, and avoid long featureless corridors without a strategy.\n\nBudget battery and storage: ~90 minutes per battery and tens of GB per hour — split long campuses into named segments you can fuse later (matching hardware configs)."},{"type":"callout","tone":"warn","title":"Initialization is sacred","body":"A botched static initialization corrupts the starting reference frame for the whole session. You cannot “fix it in the office” — you rescan."},{"type":"scenario","title":"Jobsite scenario: long corridor","situation":"You must scan a long, repetitive corridor with few unique features, then a mechanical room at the end. What’s the better approach?","choices":[{"label":"Sprint the corridor as fast as possible to save battery","feedback":"Speed without geometry cues invites drift. Slow down and add intentional revisits."},{"label":"Walk a steady pace, add loop closures / revisits at distinctive spots, then carefully cover the mechanical room","feedback":"Yes — SLAM loves overlapping views and recognizable structure.","correct":true},{"label":"Only scan the mechanical room; invent the corridor later","feedback":"Missing geometry is missing geometry. Capture what you need to deliver."}]},{"type":"quiz","id":"q-site-split","prompt":"You are documenting a multi-building campus that will need Map Fusion later. What must stay consistent?","choices":["Only the operator’s shoes","Matching L2 Pro model configs across segments (e.g. all 32/120)","Different channel counts per building for variety","Mixing PortalCam and L2 Pro in the same Map Fusion job"],"correctIndex":1,"explanation":"Map Fusion requires matching L2 Pro models — 16-channel and 32-channel scans do not fuse together."},{"type":"resource","title":"First scan procedure (L2 Pro / K2)","url":"https://www.alpinerealitycapture.com/guide/first-scan","description":"Initialization, walking practice, and clean shutdown for L2 Pro field sessions."}]},{"id":"georef-rtk","eyebrow":"Chapter 5 · Coordinates that stick","title":"RTK, GCPs, and georeferencing discipline","blocks":[{"type":"text","markdown":"## Absolute accuracy is earned before you walk\n\nL2 Pro absolute accuracy of **≤3 cm RMSE** assumes RTK or GCP coverage with no continuous unfixed gap longer than ~100 m.\n\nRelative accuracy (≤1 cm RMSE within 100 m, 3σ) describes local consistency — it is not a free pass to skip georeferencing when the client needs world coordinates."},{"type":"callout","tone":"warn","title":"RTK is attachable — not built-in","body":"On L2 Pro, RTK uses an external Standard or Survey Grade module. Seat it firmly and configure NTRIP in LixelGO before the session. Do not start scanning on Float."},{"type":"checklist","title":"Georeferencing playbook","items":["Decide datum / coordinate needs before capture (L2 Pro supports broader post-process datums than K2’s WGS84/CGCS2000-only capture constraint)","Attach and configure the RTK module when absolute coords are required","Wait for Fixed status before hitting record","Keep unfixed gaps short; plan control for long canopy / urban canyons","Use GCPs when RTK is unavailable or as reinforcement","Remember: georeferencing strategy is set up front — you cannot magically invent a solid absolute frame after a careless free scan"]},{"type":"scenario","title":"Jobsite scenario: Float at the gate","situation":"You’re at the site gate. LixelGO shows RTK Float, not Fixed. The GC is waiting. What do you do?","choices":[{"label":"Start scanning anyway — you’ll fix coordinates later somehow","feedback":"Dangerous. Float solutions embed unreliable positions. Wait for Fixed or switch to a planned GCP strategy."},{"label":"Hold for Fixed (or execute a planned GCP workflow) before recording","feedback":"Correct. Absolute accuracy starts with a trustworthy solution before the first step.","correct":true},{"label":"Remove the RTK module and pretend the job is local-only","feedback":"Only if the contract truly does not need absolute coords — and you document that choice."}]},{"type":"minigame","kind":"match","id":"game-georef-match","title":"Match the georef idea","prompt":"Pair each term with the right meaning.","pairs":[{"term":"Fixed","definition":"RTK solution ready for reliable absolute scanning"},{"term":"Float","definition":"Unreliable RTK solution — do not start measured work"},{"term":"GCP","definition":"Surveyed ground control used to lock the cloud"},{"term":"Relative accuracy","definition":"Local consistency between nearby points"}],"success":"Coordinates language locked — Fixed before you walk."}]},{"id":"lixelstudio","eyebrow":"Chapter 6 · Office HQ","title":"LixelStudio point clouds and office workflow","blocks":[{"type":"text","markdown":"## Two pipelines, one scan\n\n**LixelStudio** turns L2 Pro data into measured point clouds (LAS/LAZ/E57 and CAD-friendly paths).\n\n**LCC Studio** turns the same capture family into 3D Gaussian Splats for visualization. Decide which outputs the contract needs before you leave the site — but know one good scan can feed both."},{"type":"callout","tone":"tip","title":"Offload and preview","body":"The 1 TB SSD is not swappable — offload over USB 3.1 Gen2 or via the app workflow after projects. Preview coverage before committing to long reconstructions."},{"type":"checklist","title":"Office processing habits","items":["Import / register projects on a fast local SSD path","QA coverage and obvious holes before heavy processing","Apply control / georef QA when absolute coords are in scope","Export the formats your downstream tools actually open","Keep raw and deliverable folders named by Building-Level-Zone-Date"]},{"type":"resource","title":"LixelStudio installation & activation","url":"https://www.alpinerealitycapture.com/guide/lixelstudio-setup","description":"System requirements, activation, and how LixelStudio vs LCC Studio split responsibilities."},{"type":"quiz","id":"q-studio-role","prompt":"Which desktop application is the primary path for measured L2 Pro point clouds?","choices":["LCC Scan","LixelStudio","LixelGO only","PortalCam Studio"],"correctIndex":1,"explanation":"LixelStudio processes L2 Pro/K2 scans into measured point clouds. LCC Studio is the 3DGS visualization path."},{"type":"minigame","kind":"order","id":"game-studio-order","title":"Order the office flow","prompt":"Put the office workflow in a sensible order.","items":["QA / preview coverage","Export deliverables for CAD/BIM/share","Offload scan data from the L2 Pro","Process in LixelStudio (and LCC Studio if needed)"],"correctOrder":[2,0,3,1],"success":"Offload → QA → process → export. Clean office muscle memory."}]},{"id":"advanced-deliverables","eyebrow":"Chapter 7 · Bigger sites","title":"Map Fusion, drone options, and deliverables","blocks":[{"type":"text","markdown":"## Scale up without losing the plot\n\nLarge campuses often need **segmented captures + Map Fusion** — but only across matching L2 Pro configs.\n\nL2 Pro also supports **drone mounting** on DJI M300/M350 RTK for aerial coverage. In drone mode, remove the handheld RTK module; the aircraft provides RTK."},{"type":"callout","tone":"fun","title":"Pro move","body":"Name segments like construction documents: Campus-Building-Floor-YYYYMMDD-Seg##. Future fusion-you will thank present-you."},{"type":"scenario","title":"Jobsite scenario: roof + interiors","situation":"You need roof geometry and dense interiors for one building model. What’s a sound plan?","choices":[{"label":"Handheld interiors only and invent the roof from satellite screenshots","feedback":"Not defensible for measured work."},{"label":"Handheld L2 Pro for interiors/grounds and a planned aerial pass (or aerial-ground fusion workflow) for roof context","feedback":"Yes — combine ground and aerial coverage with a deliberate fusion plan.","correct":true},{"label":"PortalCam on a drone — it’s lighter","feedback":"PortalCam is not the L2 Pro drone workflow and won’t give the measured cloud path this chapter is about."}]},{"type":"quiz","id":"q-drone-rtk","prompt":"When mounting an L2 Pro on a compatible DJI RTK drone, what should you do with the handheld RTK module?","choices":["Leave it attached for double RTK","Remove it — the drone provides RTK in drone mode","Replace it with a PortalCam battery","Tape it to the landing gear"],"correctIndex":1,"explanation":"In drone mode, remove the L2 Pro’s own RTK module; the aircraft supplies RTK."},{"type":"minigame","kind":"rapid","id":"game-advanced-rapid","title":"Scale-up speed round","prompt":"True or false for big L2 Pro jobs.","passScore":3,"rounds":[{"statement":"Map Fusion needs matching L2 Pro channel/range configs across segments.","correct":true,"explanation":"16-channel and 32-channel segments do not fuse together."},{"statement":"L2 Pro drone mode is also supported on the K2.","correct":false,"explanation":"Drone mounting is an L2 Pro capability, not K2."},{"statement":"A done construction deliverable includes reviewed exports stakeholders can actually open.","correct":true,"explanation":"Raw SSD files are not a handoff."},{"statement":"You should update firmware for the first time while standing on a live jobsite roof.","correct":false,"explanation":"Update firmware in the office before the day of work."}],"success":"You’re thinking at campus scale — nice."}]},{"id":"debrief","eyebrow":"Chapter 8 · Mission debrief","title":"You’re ready for the certification test","blocks":[{"type":"text","markdown":"## Field → office → handoff\n\nYou can explain what the L2 Pro is for, run a disciplined LixelGO session, protect georeferencing, and route data through LixelStudio / LCC Studio into construction deliverables.\n\nNext step: pass the certification test (80%) and earn the L2 Pro medal."},{"type":"checklist","title":"Pre-test self check","items":["I know L2 Pro ≠ PortalCam (apps, outputs, and accuracy claims differ)","I can list the 16/120, 32/120, and 32/300 differences","I start RTK jobs on Fixed, not Float","I respect static initialization and clean shutdown","I know LixelStudio = point clouds, LCC Studio = 3DGS","I keep Map Fusion segments on matching hardware configs"]},{"type":"minigame","kind":"baton","id":"game-debrief-timing","title":"Steady hand timing","prompt":"Tap in the window — smooth operators beat rushed operators.","success":"Steady timing. Take the certification when you’re ready."},{"type":"quiz","id":"q-debrief-pass","prompt":"Passing score for the L2 Pro certification test is:","choices":["50%","65%","80%","100% only"],"correctIndex":2,"explanation":"You need 80% or better to earn the certification medal."},{"type":"callout","tone":"fun","title":"See you on the medal stand","body":"Open the certification test when you’re ready. Measured work rewards patient operators."}]}]}',
